import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_last, opp_last = history[-1]

    total_c = 0
    for i in range(n):
        if history[i][1] == 'C':
            total_c += 1
    total_d = n - total_c

    if n <= 2:
        if total_c == 0:
            return 'D'
        return 'C'

    w = 10 if n >= 10 else n
    recent_c = 0
    my_recent_d = 0
    for i in range(n - w, n):
        me, op = history[i]
        if op == 'C':
            recent_c += 1
        if me == 'D':
            my_recent_d += 1

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    my_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_d_streak += 1
        else:
            break

    my_c_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'C':
            my_c_streak += 1
        else:
            break

    rc = rd = cc = cd = 0
    start = 1 if n - 14 < 1 else n - 14
    for i in range(start, n):
        prev_me = history[i - 1][0]
        cur_op = history[i][1]
        if prev_me == 'D':
            if cur_op == 'C':
                rc += 1
            else:
                rd += 1
        else:
            if cur_op == 'C':
                cc += 1
            else:
                cd += 1

    denD = rc + rd
    denC = cc + cd
    rateD = float(rc) / denD if denD else 0.0
    rateC = float(cc) / denC if denC else 0.0

    hostile = (total_c * 100 <= n * 35) or (recent_c <= 2)
    cooperative = (total_c * 100 >= n * 55 and recent_c >= 5)

    if n >= 98:
        return 'D'

    if hostile:
        return 'D'

    # Opponent has never defected yet: exploit, but first wait one round
    # to observe the response to a fresh defection.
    if total_d == 0 and n >= 5:
        if denD == 0:
            if my_last == 'C':
                return 'D'
            return 'C'
        if rateD >= 0.5:
            return 'D'
        return 'C'

    # Detect non-reactive / patterned / exploitable defection streaks.
    unprovoked_recent = False
    i = n - 16
    if i < 0:
        i = 0
    while i < n and not unprovoked_recent:
        if history[i][1] == 'D':
            begin = i
            while i < n and history[i][1] == 'D':
                i += 1
            if i - begin >= 2:
                prev = begin - 1
                if prev < 0 or history[prev][0] == 'C':
                    unprovoked_recent = True
        else:
            i += 1

    unprovoked_current = False
    if opp_d_streak >= 2:
        begin = n - opp_d_streak
        prev = begin - 1
        if prev < 0 or history[prev][0] == 'C':
            unprovoked_current = True

    nonreactive = False
    if denD >= 2 and denC >= 2:
        if rateD >= 0.45 and (rateD + 0.20 >= rateC or rateC < 0.50):
            nonreactive = True
    elif denD >= 1 and cooperative:
        if rateD >= 0.70 and recent_c >= 7:
            nonreactive = True

    if (unprovoked_recent or unprovoked_current) and recent_c >= 6 and (denD < 3 or rateD >= 0.25):
        nonreactive = True

    # Short punishment from a cooperative opponent: back off and recover.
    if (opp_last == 'D' and my_last == 'D' and cooperative and recent_c >= 6
            and opp_d_streak <= 2 and my_d_streak <= 2 and rateD <= 0.25 and rd >= 2):
        return 'C'

    # Long cooperative-defection burst: one recovery probe after four Ds.
    if (opp_last == 'D' and opp_d_streak == 4 and my_last == 'D'
            and cooperative and recent_c >= 5 and rateD <= 0.30):
        return 'C'

    # If opponent appears non-reactive or exploitable, push for points.
    if nonreactive:
        if opp_last == 'C':
            # If we have been defecting a long time and they finally punish,
            # pause briefly; otherwise keep harvesting.
            if my_d_streak >= 6 and rd >= 2 and rateD < 0.50:
                return 'C'
            return 'D'
        if my_last == 'D' and cooperative and rateD < 0.20 and rd >= 3 and opp_d_streak <= 3:
            return 'C'
        return 'D'

    # Reactive mode: mostly generous tit-for-tat.
    if opp_last == 'D':
        if my_last == 'D':
            if cooperative and recent_c >= 6 and opp_d_streak <= 3:
                return 'C'
            return 'D'
        if opp_d_streak == 1 and recent_c >= 8 and total_c * 100 >= n * 70:
            return 'C'
        return 'D'

    # Opponent cooperated last.
    if cooperative and recent_c >= 7 and rc > rd and rateD >= 0.60:
        return 'D'

    # Deterministic safe probe against near-constant cooperation.
    if (cooperative and recent_c >= 9 and my_recent_d == 0
            and total_c * 100 >= n * 90 and n >= 12 and n % 20 == 10):
        return 'D'

    # Sparse random probe when very cooperative and we have not defected recently.
    if (cooperative and recent_c >= 9 and my_recent_d == 0
            and total_c * 100 >= n * 70 and n >= 25 and rng.random() < 0.03):
        return 'D'

    # If our latest defection has no observed response yet, stabilize.
    if my_last == 'D' and opp_last == 'C' and denD == 0:
        return 'C'

    return 'C'
